JOB_Q = queue.Queue()


def _worker_loop():
    while True:
        fn, args = JOB_Q.get()
        try:
            fn(*args)
        except Exception:
            log_exc("_worker_loop", getattr(fn, "__name__", "?"))
        finally:
            JOB_Q.task_done()


