_SUB_LANGS_TOP = ['Russian', 'English', 'Polish', 'Czech', 'Romanian', 'German',
                  'French', 'Italian', 'Spanish', 'Portuguese']
_SUB_LANG_OK = set(_SUB_LANGS_ALL)
_MATERIAL_ORDERS = {"video_first", "images_first", "alternate", "alphabetical", "random"}
_QUALITY_OK = ("144p", "240p", "360p", "480p", "720p", "1080p")


def _render_config_from_params(p):
    """UI-форма рендера → конфиг render_worker. Бокс: force libx264 veryfast — НЕ потому что
    NVENC сломан (это было про RunPod; на минской 4070S NVENC жив), а по бенчу 15.07.2026:
    на слайдшоу x264 быстрее NVENC (12.9x vs 11.3x) и БИТРЕЙТ nvenc cq26 = +61%…×3.2 к crf26;
    на KB nvenc даёт лишь +11% скорости. Снимать force → video-тяжёлые джобы уйдут в nvenc
    и раздуются по размеру. Если появится нода без живого x264-запаса — пересмотреть.
    Переходы: none→без fade; fast→fade+fast_batch_stitch (94%, ~2мин); smooth→fade+полные (100%, ~5мин).
    Паритет с десктопом (2026-07-10): sync_audio/уникализация/винтаж/паузы/громкости/порядок/fade/KB-зум."""
    q = (p.get("quality") or "1080p").strip()
    if q not in _QUALITY_OK:
        q = "1080p"
    tr = (p.get("transitions") or "fast").strip()   # none | fast
    # ИСПРАВЛЕНО 03.09.2026: режимов было три, а различались два. «Быстрые» и «Плавные»
    # давали одно и то же — ниже единственное использование tr: enable_fade = tr != "none".
    # Разницы в коде не существовало (комментарий про замер 03.08 объясняет почему).
    # Старое значение "smooth" в сохранённых пресетах читается как «переходы включены».
    if tr == "smooth":
        tr = "fast"
    # «Плавные» переходы отключены осознанно (замер 03.08): они пересобирали ВЕСЬ ролик ради
    # стыков пачек (×3.4 по времени) и съедали по fade на каждом стыке — картинки уезжали
    # вперёд накопительно. Настоящие кроссфейды делаются ВНУТРИ пачек и одинаковы в обоих
    # режимах, поэтому склейка всегда stream-copy. crf оставлен 26: понижение до 24 на сервере
    # дало 0% скорости (пресет тут и так veryfast) при +24% размера файла.
    rs = {"force_encoder": "libx264", "cpu_preset": "veryfast", "crf": 26,
          "fast_batch_stitch": True,
          # ffmpeg под nice+10 (воркер применяет в run_ffmpeg_command, POSIX-only): при
          # параллельных рендерах 40-60 потоков x264 душили whisper-процесс (python, GPU
          # простаивал на 9-17% util) → фаза синхрона растягивалась с ~2 до 5-10+ мин
          # (live-профиль 15.07). Приоритет python-воркера выше ffmpeg → whisper дышит,
          # энкод забирает всё остальное. Замер до/после — в памяти minsk-render-node.
          "process_priority": "low"}
    _lang_raw = (p.get("subtitle_lang") or "Russian").strip()
    _lang = _SUB_LANG_CANON.get(_lang_raw, _lang_raw)
    if _lang not in _SUB_LANG_OK:
        _lang = "Russian"
    # video_first: клипы NNN_video.mp4 — это анимированные ПЕРВЫЕ сцены (first_n), их картинки
    # исключены через googler_video_references. images_first уводил клипы В КОНЕЦ ролика →
    # весь ряд картинок сдвигался относительно озвучки (баг «рендер всё напутал», 03.07).
    # Теперь порядок выбирается в «Расширенных настройках»; дефолт остаётся video_first.
    mo = (p.get("material_order") or "video_first").strip()
    if mo not in _MATERIAL_ORDERS:
        mo = "video_first"
    cfg = {
        "quality": q,
        "enable_fade": (tr != "none"),
        "enable_kenburns": _truthy(p.get("kenburns"), False),
        "add_subtitles": _truthy(p.get("subtitles"), False),
        "subtitle_language": _lang,
        "material_order": mo,
        "use_video_audio": _truthy(p.get("use_video_audio"), False),
        # дефолты True — как у воркера/десктопа: старые задачи без ключей ведут себя по-прежнему
        "sync_audio": _truthy(p.get("sync_audio"), True),
        # УБРАНО 03.09.2026 «distribute_evenly»: значение доезжало до рендера и не читалось
        # (render_worker.py:971 — единственное упоминание, только присваивание). Настройка,
        # которая ничего не делает, — это правило №2 ТЗ. Само присваивание в воркере
        # снимается на этапе чистки движков; здесь убран транспорт.
        "randomize_metadata": _truthy(p.get("randomize_metadata"), False),
        "vintage_effect": _truthy(p.get("vintage_effect"), False),
        "render_settings": rs,
    }
    for k in ("min_image_duration", "max_image_duration", "fade_duration", "kenburns_zoom",
              "pause_duration"):
        try:
            if p.get(k) not in (None, ""):
                cfg[k] = float(p[k])
        except Exception:
            pass
    try:
        if p.get("pause_interval") not in (None, ""):
            cfg["pause_interval"] = max(0, int(float(p["pause_interval"])))
    except Exception:
        pass
    try:
        if p.get("stock_video_limit") not in (None, ""):
            cfg["stock_video_limit"] = max(0, int(float(p["stock_video_limit"])))   # 0 = брать все
    except Exception:
        pass
    cfg["stock_video_cycle"] = _truthy(p.get("stock_video_cycle"), True)            # повторять по кругу
    # громкости в UI — проценты (как в десктопе), воркер ждёт множитель 0.0–2.0
    for k_ui, k_cfg in (("main_audio_volume", "main_audio_volume"),
                        ("video_audio_volume", "video_audio_volume")):
        try:
            if p.get(k_ui) not in (None, ""):
                cfg[k_cfg] = max(0.0, min(2.0, float(p[k_ui]) / 100.0))
        except Exception:
            pass
    # глобальный масштаб/смещение медиа
    try:
        if p.get("media_scale_pct") not in (None, ""):
            cfg["media_scale_pct"] = max(10.0, min(400.0, float(p["media_scale_pct"])))
    except Exception:
        pass
    for k in ("media_offset_x", "media_offset_y"):
        try:
            if p.get(k) not in (None, ""):
                cfg[k] = max(-2000, min(2000, int(float(p[k]))))
        except Exception:
            pass
    # музыка и вставки: settings.render_media (JSON) → файловые ключи конфига.
    # Пути ОТНОСИТЕЛЬНЫЕ ("_RENDER_MEDIA/<kind>/<file>") — render_worker резолвит от project_dir,
    # на рендер-ноде файлы приезжают в общем tar (render_assets).
    rm = p.get("render_media")
    if isinstance(rm, str) and rm.strip():
        try:
            rm = json.loads(rm)
        except Exception:
            rm = None
    if isinstance(rm, dict):
        def _rel(f):
            return "/".join((_RM_DIR, str(f).replace("..", "").lstrip("/")))
        _bg = rm.get("bg") or {}
        if _bg.get("file"):
            cfg["background_audio_file"] = _rel(_bg["file"])
            try:
                cfg["background_audio_volume"] = max(0.0, min(2.0, float(_bg.get("vol", 20)) / 100.0))
            except Exception:
                pass
        _end = rm.get("end") or {}
        if _end.get("file"):
            cfg["end_track_file"] = _rel(_end["file"])
            try:
                cfg["end_track_volume"] = max(0.0, min(2.0, float(_end.get("vol", 100)) / 100.0))
            except Exception:
                pass
        if [f for f in (rm.get("stock") or []) if isinstance(f, str) and f]:
            # воркеру нужна ПАПКА: он сам обходит её и подмешивает материалы к картинкам
            cfg["extra_materials_dir"] = "/".join((_RM_DIR, "stock"))
        _intro = [f for f in (rm.get("intro") or []) if isinstance(f, str) and f]
        if _intro:
            cfg["intro_video_files"] = [_rel(f) for f in _intro]
        _ovl = []
        for o in (rm.get("overlays") or []):
            if isinstance(o, dict) and o.get("file"):
                try:
                    _op = max(0.0, min(1.0, float(o.get("opacity", 50)) / 100.0))
                except Exception:
                    _op = 0.5
                _ovl.append({"path": _rel(o["file"]), "opacity": _op})
        if _ovl:
            cfg["overlays"] = _ovl
    # Закреплённый на claim набор основной озвучки едет на ноду как есть (образец —
    # боевой кабинет). Новая нода прогонит этот список через тот же render_narration и
    # возьмёт ровно его; старая про ключ не знает — её страхует фильтр материалов в
    # render_assets. Пути относительные: корень проекта на ноде другой, а раскладка
    # внутри tar та же.
    if "narration_files" in p:
        cfg["narration_files"] = p["narration_files"]
    return cfg


# Пульс машины рендера отдельно от выдачи работ. Нода шлёт его раз в 30 секунд, и
# нам он нужен не ради красоты: в нём видно место на диске, сколько роликов лежит
# неотданными и какие версии пуллера и рендерера там стоят. Боевая нода эту ручку
# зовёт с 18.09; у нас её не было, и в её журнале раз в полминуты капала ошибка —
# то есть на настоящую поломку смотрели бы сквозь шум из ложных.
RENDER_HEALTH_KEY = "render_node_health"


@app.post("/api/render/node-health")
async def render_node_health(request: Request):
    """Пульс машины рендера: место, очередь на отдачу, версии. Ничего не запускает."""
    _require_puller(request)
    try:
        said = await request.json()
    except Exception:                                              # noqa: BLE001
        said = {}
    if not isinstance(said, dict):
        said = {}
    host = str(said.get("host") or request.headers.get("X-Render-Host") or "render")[:40]
    now = time.time()

    def _num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return None

    free_bytes = _num(said.get("free_bytes"))
    row = {
        "at": now,
        "free_gb": round(free_bytes / (1024 ** 3), 2) if free_bytes is not None else None,
        # Сколько готового лежит неотданным и сколько из этого просрочено: ролик,
        # который нода собрала, но не смогла отдать, — это потерянные деньги и время,
        # и видно это только отсюда.
        "outbox_gb": (round(_num(said.get("outbox_retained_bytes")) / (1024 ** 3), 2)
                      if _num(said.get("outbox_retained_bytes")) is not None else None),
        "outbox_attention": int(_num(said.get("outbox_attention")) or 0),
        "outbox_stuck": int(_num(said.get("outbox_stuck")) or 0),
        "active_jobs": int(_num(said.get("active_jobs")) or 0),
        # Версии — хвостами: полный хэш на экране не нужен, а «та ли версия стоит»
        # по хвосту видно сразу.
        "puller": str(said.get("puller_sha256") or "")[:12],
        "worker": str(said.get("worker_sha256") or "")[:12],
    }
    c = db()
    try:
        prev = c.execute("SELECT v FROM admin_state WHERE k=?",
                         (RENDER_HEALTH_KEY,)).fetchone()
        try:
            state = json.loads((prev[0] if prev else "") or "{}")
        except Exception:                                          # noqa: BLE001
            state = {}
        if not isinstance(state, dict):
            state = {}
        state[host] = row
        c.execute("INSERT OR REPLACE INTO admin_state(k,v,updated) VALUES(?,?,?)",
                  (RENDER_HEALTH_KEY, json.dumps(state, ensure_ascii=False), now))
        # Тот же снимок места, что кладёт выдача работ: тревога «мало места» должна
        # знать про машину рендера, даже когда очередь пуста и claim молчит.
        if row["free_gb"] is not None:
            note_node_disk(c, host, "render", row["free_gb"], None)
        c.commit()
    finally:
        c.close()
    return {"ok": True}


@app.post("/api/render/claim")
async def render_claim(request: Request):
    """Пуллер забирает старейшее queued render-задание (+ lease, + возврат зависших в очередь)."""
    _require_puller(request)
    # Отметка живости рендер-ноды. Прогресс (claimed) показывает её только когда рендер
    # ИДЁТ; при пустой очереди «нода жива» и «нода умерла» выглядят одинаково — а разница
    # в том, начнётся ли следующий рендер вообще. Опрос ручки claim и есть тот пульс.
    _RENDER_POLL["ts"] = time.time()
    _RENDER_POLL["polls"] += 1
    try:
        _RENDER_POLL["peer"] = (request.client.host if request.client else "") or ""
    except Exception:
        pass
    # 04.09.2026: нода сообщает своё свободное место тем же опросом. Раньше сервер
    # знал только про свой диск, и тревога «мало места» не говорила, на какой машине.
    try:
        said = await request.json()
    except Exception:
        said = {}
    if isinstance(said, dict) and said.get("free_gb") is not None:
        _c = db()
        try:
            note_node_disk(_c, said.get("host") or "render", said.get("role") or "render",
                           said.get("free_gb"), said.get("total_gb"))
            _c.commit()
        except Exception:
            log_exc("render_claim/node_disk")
        finally:
            _c.close()
    # Пауза из админ-панели: нода продолжает опрашивать ручку, но заданий не получает.
    # Уже начатый на ноде рендер идёт до конца — его результат примут как обычно.
    if _queue_paused("render"):
        return JSONResponse({"job": None})
    c = db()
    cutoff = time.time() - RENDER_LEASE_SEC
    c.execute("UPDATE queue_tasks SET status='queued', claimed=NULL, claim_token=NULL "
              "WHERE kind='render' AND status='running' AND (claimed IS NULL OR claimed < ?)", (cutoff,))
    c.execute("UPDATE gen_jobs SET status='queued',error=NULL WHERE id IN ("
              "SELECT job_id FROM queue_tasks WHERE kind='render' AND status='queued') "
              "AND status='running'")
    c.commit()
    # Дальше — одна транзакция на «выбрал строку → закрепил озвучку → отдал задачу».
    # BEGIN IMMEDIATE берёт писательскую блокировку сразу, а не на первом UPDATE: иначе
    # между SELECT кандидатов и UPDATE помещается второй пуллер, и снимок озвучки,
    # записанный в params, может оказаться не от того захвата, который реально поехал
    # рендерить. busy_timeout=30000 уже стоит (см. db()), поэтому при занятой БД ручка
    # подождёт, а не ответит «нет задач».
    c.execute("BEGIN IMMEDIATE")
    candidates = c.execute(
        "SELECT r.* FROM queue_tasks r "
        "WHERE r.kind='render' AND r.status='queued' "
        "AND NOT EXISTS (SELECT 1 FROM queue_tasks w "
        "WHERE w.tenant_id=r.tenant_id AND w.project_id=r.project_id "
        "AND w.kind!='render' AND w.status IN ('queued','running')) "
        "ORDER BY r.created ASC LIMIT 100"
    ).fetchall()
    # Проект под уборкой пропускаем так же, как проект с неготовыми материалами:
    # задача остаётся в очереди и уедет следующим опросом, когда аренда снимется.
    # Отдать её сейчас — значит рендерить по исходникам, которые прямо сейчас удаляют.
    row = next((r for r in candidates
                if not _storage_project_held(c, r["project_id"])
                and _render_inputs_ready(r["tenant_id"], r["project_id"])), None)
    if not row:
        c.commit(); c.close()
        return JSONResponse({"job": None})
    jid = row["job_id"]
    # ЗАКРЕПЛЕНИЕ ОЗВУЧКИ. До этой правки сервер проверял только факт «есть хоть один
    # mp3», а какие именно файлы попадут в дорожку, решала нода: она сканирует каталог
    # проекта рекурсивно и склеивает ВСЁ найденное. Значит набор зависел от того, что
    # лежало на диске в момент рендера, а не от того, что решил кабинет, — и мог
    # измениться после постановки в очередь (ручная заливка файла, отложенный рендер).
    # Теперь набор выбирается здесь, один раз, и уезжает вместе с задачей.
    try:
        _params = json.loads(row["params"] or "{}")
        if not isinstance(_params, dict):
            _params = {}
    except Exception:
        _params = {}
    _project = _get_project(row["tenant_id"], row["project_id"])
    try:
        _psnap = _psettings(_project) if _project else {}
    except Exception:
        _psnap = {}
    # Движок и файлы фона/финального трека живут в настройках проекта, форма рендера их
    # перекрывает — выбору озвучки нужна именно такая склейка.
    _snapshot = {**(_psnap or {}), **_params}
    # Закрепление ПРЕДЫДУЩЕГО захвата в расчёт не берём: иначе модуль просто проверил бы
    # старый список и вернул его. Перезахват случается после упавшей попытки, и человек
    # к этому моменту мог озвучку починить — удалить лишнюю папку, переозвучить нужным
    # движком. Унаследованный список такую починку не увидел бы никогда: удалённый файл
    # из него навсегда превратил бы задачу в «файл основной озвучки отсутствует», а новые
    # файлы остались бы за бортом. (Боевой кабинет здесь наследует — считаю это его
    # историческим упущением, в отчёте сказано.)
    _snapshot.pop("narration_files", None)
    try:
        from render_narration import select_narration
        _selected = select_narration(_project_dir(row["tenant_id"], row["project_id"]), _snapshot)
        if not _selected:
            raise ValueError("Нет файлов основной озвучки")
    except ValueError as exc:
        # Выбор не состоялся — это ответ человеку, а не «нет задач». Раньше непригодная
        # к рендеру задача просто пропускалась в цикле кандидатов и висела в очереди
        # молча, без единой строчки о причине.
        c.execute("UPDATE queue_tasks SET status='error',error=?,finished=? WHERE job_id=? AND status='queued'",
                  (str(exc), _now(), jid))
        c.execute("UPDATE gen_jobs SET status='error',error=? WHERE id=?", (str(exc), jid))
        c.commit(); c.close()
        _log_line(jid, "⛔ рендер не начат: " + str(exc))
        return JSONResponse({"job": None})
    except Exception:
        # Модуль не импортировался или сломался. Отдать задачу вслепую нельзя: нода
        # склеит всё, что найдёт, — то есть вернётся ровно тот дефект, ради которого
        # закрепление и делалось. Задача остаётся в очереди, проект не ломаем.
        c.rollback(); c.close()
        log_exc("render_claim/narration")
        return JSONResponse({"job": None, "wait_reason": "narration"})
    _params["narration_files"] = _selected
    claim_token = secrets.token_urlsafe(24)
    cur = c.execute(
        # params переписываются ТОЙ ЖЕ транзакцией, что и claim_token: закрепление,
        # которое легло бы отдельным коммитом, при перезахвате оставило бы задачу с
        # чужим списком файлов. Квитанция предыдущего прогона (render_sha256 и соседи)
        # здесь же обнуляется — она относится к старому mp4, а не к тому, который
        # нода только начинает считать.
        "UPDATE queue_tasks SET status='running', started=?, claimed=?, progress=0, stage='claimed', "
        "error=NULL, claim_token=?, params=?, render_sha256=NULL, render_size=NULL, render_error_sha256=NULL "
        "WHERE job_id=? AND status='queued' AND NOT EXISTS (SELECT 1 FROM queue_tasks w "
        "WHERE w.tenant_id=queue_tasks.tenant_id AND w.project_id=queue_tasks.project_id "
        "AND w.kind!='render' AND w.status IN ('queued','running'))",
        (_now(), time.time(), claim_token, json.dumps(_params, ensure_ascii=False), jid),
    )
    if cur.rowcount == 1:
        c.execute("UPDATE gen_jobs SET status='running',error=NULL WHERE id=?", (jid,))
    c.commit()
    t = c.execute("SELECT * FROM queue_tasks WHERE job_id=?", (jid,)).fetchone()
    c.close()
    if cur.rowcount != 1 or not t or t["status"] != "running":
        return JSONResponse({"job": None})
    proj = _get_project(t["tenant_id"], t["project_id"])
    # база = settings проекта (render_media и пр. живут там), поверх — params задачи (свежая форма)
    try:
        _base = _psettings(proj) if proj else {}
    except Exception:
        _base = {}
    cfg = _render_config_from_params({**_base, **json.loads(t["params"] or "{}")})
    return JSONResponse({"job": {"job_id": jid, "claim_token": claim_token,
                                 "tenant_id": t["tenant_id"], "project_id": t["project_id"],
                                 "name": (proj["name"] if proj else t["project_id"]), "config": cfg}})


@app.get("/api/render/{jid}/assets")
async def render_assets(jid: int, request: Request):
    """Стримит tar.gz материалов проекта (googler/ + _ASSETS/ + _FINAL_AUDIO_*/)."""
    _require_puller(request)
    c = db(); t = c.execute("SELECT tenant_id, project_id, status, claim_token, params FROM queue_tasks WHERE job_id=? AND kind='render'", (jid,)).fetchone(); c.close()
    if not t:
        raise HTTPException(404)
    _require_render_claim(request, t)
    if t["status"] != "running":
        raise HTTPException(409, "render job уже не активен")
    proj = _project_dir(t["tenant_id"], t["project_id"])
    # 🎧 Автозвук ОТКЛЮЧЁН 03.09.2026 — фича выкачена наполовину.
    # Серверная половина работала: auto_sound.prepare() платно ходит в модель (codex exec),
    # подбирает mp3 и пишет _RENDER_MEDIA/sfx/sound_plan.json. Но боевой рендерер на Минске
    # (render_worker.py, 6117 строк) про этот файл не знает: ни _load_sound_plan,
    # ни _apply_auto_sound в нём нет — они есть только в маковской версии на 6210 строк,
    # которая на ноду не залита. Итог: один оплаченный вызов на проект в никуда.
    # Включать обратно ТОЛЬКО вместе с выкаткой рендерера на Минск (см. auto_sound.py).
    # «googler video» — сгенерированные видео-клипы: БЕЗ них рендер на боксе соберёт слайдшоу без видео (audit 02.07)
    items = [d for d in ("googler", "Images", "googler video", "_ASSETS", "_RENDER_MEDIA") if os.path.isdir(os.path.join(proj, d))]
    # ОЗВУЧКА: в tar кладём только закреплённые на claim файлы, а не все папки
    # _FINAL_AUDIO_*. Рендерер (и боевой 02.09, и наш стендовый) обходит каталог проекта
    # рекурсивно и склеивает ВСЁ найденное аудио — отдай ему две папки, и в ролике
    # прозвучат обе озвучки подряд. Про ключ narration_files старая нода не знает, а вот
    # «чего нет в архиве, то не склеится» понимают обе. Поэтому предохранитель стоит
    # здесь: один и тот же звук на любой ноде, не дожидаясь её обновления.
    try:
        _pinned = json.loads(t["params"] or "{}").get("narration_files")
    except Exception:
        _pinned = None
    _audio, _lost = [], []
    if isinstance(_pinned, list) and _pinned:
        for _rel in _pinned:
            _rel = str(_rel).replace("\\", "/").lstrip("/") if isinstance(_rel, str) else ""
            if not _rel or ".." in _rel.split("/") or os.path.isabs(_rel) \
                    or not os.path.isfile(os.path.join(proj, _rel)):
                _lost.append(str(_rel))
                continue
            # Файл, который и так уезжает целой папкой (озвучка в Images/ у старых
            # проектов), вторым членом архива не кладём: tar дубль примет, но архив
            # распухнет, а на ноде распакуется то же самое.
            if _rel.split("/")[0] not in items:
                _audio.append(_rel)
        if _lost:
            # Закрепление есть, а файла на диске нет: проект почистили между выдачей
            # задачи и скачиванием материалов. Отдать архив с ЧАСТЬЮ озвучки хуже всего —
            # ролик соберётся, будет выглядеть готовым и молча потеряет кусок текста.
            raise HTTPException(409, "закреплённая озвучка пропала из проекта ("
                                + ", ".join(_lost[:3]) + ") — поставьте рендер заново")
        items += _audio
    else:
        # Задача захвачена до выкатки закрепления (params без narration_files) — везём
        # всё, как раньше. Отдельной миграции для таких задач не нужно, они доедут сами.
        items += [os.path.basename(p) for p in glob.glob(os.path.join(proj, "_FINAL_AUDIO_*")) if os.path.isdir(p)]
    if not items:
        raise HTTPException(404, "нет материалов")
    # карта «картинка→видео»: абсолютные VPS-пути внутри не существуют на GPU-боксе → относим к project_dir
    # (render_worker понимает относительные: см. render_worker.py ~4360)
    vrf = os.path.join(proj, "googler_video_references.json")
    if os.path.isfile(vrf):
        try:
            _lst = json.load(open(vrf, encoding="utf-8"))
            if isinstance(_lst, list):
                _base = proj.rstrip(os.sep) + os.sep
                _rel = [os.path.relpath(str(p), proj) if str(p).startswith(_base) else str(p) for p in _lst]
                with open(vrf, "w", encoding="utf-8") as _f:
                    json.dump(_rel, _f, ensure_ascii=False)
            items.append("googler_video_references.json")
        except Exception:
            pass
    proc = subprocess.Popen(["tar", "czf", "-", "-C", proj] + items, stdout=subprocess.PIPE)

    def _gen():
        try:
            while True:
                chunk = proc.stdout.read(262144)
                if not chunk:
                    break
                yield chunk
        finally:
            try: proc.stdout.close()
            except Exception: pass
            proc.wait()
    return StreamingResponse(_gen(), media_type="application/gzip",
                             headers={"Content-Disposition": f"attachment; filename=assets_{jid}.tar.gz"})


@app.post("/api/render/{jid}/progress")
async def render_progress(jid: int, request: Request):
    """Пуллер шлёт прогресс (urlencoded: pct, stage) + обновляет lease."""
    _require_puller(request)
    d = await _form(request)
    try:
        pct = float(d.get("pct") or 0)
    except Exception:
        pct = 0
    stage = (d.get("stage") or "")[:120]
    token = request.headers.get("X-Render-Claim", "")
    c = db(); cur = c.execute("UPDATE queue_tasks SET progress=?, stage=?, claimed=? "
                              "WHERE job_id=? AND kind='render' AND status='running' AND claim_token=?",
                              (pct, stage, time.time(), jid, token)); c.commit(); c.close()
    if cur.rowcount != 1:
        raise HTTPException(409, "render job отменён или завершён")
    return JSONResponse({"ok": True})


# Потолок принимаемого mp4. Наш самый длинный ролик — двухчасовой, это единицы гигабайт;
# 64 GiB — не рабочий предел, а защита от ноды, которая льёт в нас поток без конца.
# В env, чтобы поднять или опустить без правки кода; умолчание — как в бою.
# `or` вокруг чтения обязателен: в .env переменная живёт как `VS_RENDER_MAX_BYTES=`
# (закомментировали значение, строку оставили), и тогда getenv отдаёт ПУСТУЮ строку,
# а не умолчание. `int("")` — ValueError на импорте, то есть кабинет не поднимается
# целиком из-за настройки одной ручки. Так сделаны соседние настройки (VS_RETENTION_*).
RENDER_MAX_BYTES = int((os.environ.get("VS_RENDER_MAX_BYTES", "") or "").strip()
                       or 64 * 1024 ** 3)


def _render_row(jid, c=None):
    """Строка render-задачи ЦЕЛИКОМ; нет такой задачи — 404.

    Именно целиком, а не перечнем колонок, как было: квитанции нужны и claim_token,
    и output_rel, и render_sha256 — при списке колонок каждое новое поле кончается
    вопросом «почему в ответе None».
    """
    own = c is None
    c = c or db()
    try:
        t = c.execute("SELECT * FROM queue_tasks WHERE job_id=? AND kind='render'", (jid,)).fetchone()
    finally:
        if own:
            c.close()
    if not t:
        raise HTTPException(404, "нет такого рендера")
    return t


def _render_receipt(t):
    """Квитанция о судьбе рендера — то, чем нода доказывает себе, что файл доехал целым.

    Считается ПО ДИСКУ, а не по строке в базе. «В базе done» и «лежит тот самый файл» —
    разные утверждения: по второму нода удаляет свою единственную копию ролика, и
    ошибка здесь стоит оплаченного рендера.

    Дорого (одно чтение mp4 на выдачу), зато честно. Нода зовёт квитанцию редко:
    перед повторной заливкой и при примирении после перезапуска.

    Рендеры, принятые ДО этой правки, хэша не имеют — по ним квитанция не выдаётся
    (503 «держи копию»), а не сочиняется. На скачивание и заливку это не влияет: там
    читается output_rel, и он у старых строк на месте.
    """
    receipt = {"ok": True, "accepted": False, "job_id": t["job_id"], "status": t["status"]}
    if t["status"] == "done":
        path = os.path.join(_project_dir(t["tenant_id"], t["project_id"]), t["output_rel"] or "")
        if not t["render_sha256"] or not os.path.isfile(path) or os.path.getsize(path) != t["render_size"]:
            raise HTTPException(503, "квитанция не подтверждена файлом; MP4 на ноде необходимо сохранить")
        h = hashlib.sha256()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                h.update(chunk)
        if h.hexdigest() != t["render_sha256"]:
            raise HTTPException(503, "контрольная сумма MP4 изменилась; сохраните копию на ноде")
        receipt.update(accepted=True, sha256=h.hexdigest(), size=t["render_size"])
    elif t["status"] == "error" and t["render_error_sha256"]:
        receipt.update(accepted=True, error_sha256=t["render_error_sha256"])
    elif t["status"] != "running":
        # running → accepted:false, это сигнал ноде «я тебя не приняла, заливай».
        # Остальное (cancelled, queued после возврата аренды) — уже не её результат.
        raise HTTPException(409, "задача отменена или передана другому исполнителю")
    return receipt


def _render_fsync_dir(path):
    """Сбросить на диск сам КАТАЛОГ: имя файла живёт в нём, и без этого переименование
    может не пережить потерю питания (файл есть, имени нет)."""
    fd = os.open(path, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


RENDER_INCOMING_PREFIX = ".incoming-"
# Возраст, после которого недокачанный `.incoming-*` считается брошенным.
# Умолчание выбрано по времени жизни ЖИВОЙ заливки, а не на глаз: нода льёт тело
# одним запросом с timeout=1200 c (dev/render_puller.post_done), то есть у работающей
# доставки mtime файла обновляется минимум раз в двадцать минут, а вся она укладывается
# в двадцать минут целиком. Шесть часов — восемнадцатикратный запас: снести идущую
# доставку такой порог не может, а огрызок от вчерашнего OOM переживёт максимум один
# час до ближайшего тика. Спорное место — именно эта цифра, поэтому она в настройке.
RENDER_INCOMING_MAX_AGE_SEC = float((os.environ.get("VS_RENDER_INCOMING_MAX_AGE_SEC", "")
                                     or "").strip() or 6 * 3600)


def _render_staged_file(directory):
    """Открытый временный файл В ТОЙ ЖЕ папке, куда ляжет результат.

    Та же файловая система → os.replace атомарен. Точка в начале имени прячет
    недокачанное тело от glob('*.mp4'): и от наших уборщиков, и от find_video,
    который при двух mp4 в папке честно отказывается угадывать.
    """
    os.makedirs(directory, exist_ok=True)
    fd, path = tempfile.mkstemp(prefix=RENDER_INCOMING_PREFIX, dir=directory)
    return os.fdopen(fd, "wb"), path


def _sweep_incoming_renders(max_age_sec=None):
    """Снести недокачанные тела рендера, которые не убрал за собой их же запрос.

    `finally` в `render_result` закрывает штатные исходы — 400, 409, обрыв соединения.
    Он не закрывает НЕштатный: SIGKILL при деплое, падение процесса, OOM-killer. Тогда
    файл остаётся навсегда, и это худший вид мусора — невидимый. Имя начинается с точки,
    поэтому огрызок не попадает ни в `find_video` (он смотрит `*.mp4`), ни в подсчёт
    занятого места, ни в уборку исходников (она ходит по `Images`/`googler`/озвучкам, а
    `render/` не трогает вовсе). Несколько прерванных заливок двухчасового ролика — это
    десятки гигабайт, которых «нет» ни в одном отчёте.

    Удаляем ТОЛЬКО по возрасту: файл, в который прямо сейчас пишут, моложе порога.
    Симлинк под таким именем не трогаем вовсе — мы кладём сюда обычные файлы, а
    подменённое имя означает, что по этой ссылке удалили бы чужое.
    """
    horizon = time.time() - (RENDER_INCOMING_MAX_AGE_SEC if max_age_sec is None
                             else float(max_age_sec))
    removed = freed = 0
    pattern = os.path.join(TENANTS_DIR, "*", "projects", "*", "render",
                           RENDER_INCOMING_PREFIX + "*")
    for path in glob.glob(pattern):
        try:
            if os.path.islink(path) or not os.path.isfile(path):
                continue
            info = os.lstat(path)
            if info.st_mtime > horizon:
                continue
            os.unlink(path)
        except OSError:
            continue                      # исчез сам или нет прав — не наша забота
        removed += 1
        freed += info.st_size
    if removed:
        log_info(f"брошенных тел рендера убрано: {removed}, освобождено {freed} байт "
                 f"(старше {int(RENDER_INCOMING_MAX_AGE_SEC)} с)")
    return {"removed": removed, "freed_bytes": freed}


@app.get("/api/render/{jid}/receipt")
async def render_receipt(jid: int, request: Request):
    """Нода спрашивает «мой результат принят?» — прежде чем заливать ролик заново.

    Ручка появилась не для красоты: боевая нода (файлы 14.09) зовёт её сама. Пока её
    нет, нода получает 404, считает доставку несостоявшейся, перезаливает готовый mp4
    до двадцати раз и уходит в карантин, держа гигабайты на своём диске.
    """
    _require_puller(request)
    t = _render_row(jid)
    _require_render_claim(request, t)
    return JSONResponse(await run_in_threadpool(_render_receipt, t))


@app.post("/api/render/{jid}/result")
async def render_result(jid: int, request: Request):
    """Пуллер отдаёт результат: ?status=done с mp4 в СЫРОМ body (без multipart), либо ?status=error&error=...

    Тело сперва ложится во временный `.incoming-*`, сверяется с Content-Length и
    X-Render-SHA256 и только потом переезжает на место одним os.replace. Раньше поток
    писался прямо в финальный файл: оборванная заливка оставляла обрезанный mp4 под
    штатным именем, и на YouTube уезжал именно он.

    Ответ — квитанция (ok/accepted/job_id/status/sha256/size), а не {"ok": true}:
    по ней нода решает, можно ли удалить свою единственную копию ролика.
    """
    _require_puller(request)
    status = request.query_params.get("status", "done")
    if status not in ("done", "error"):
        raise HTTPException(400, "неверный статус рендера")
    t = _render_row(jid)
    _require_render_claim(request, t)
    expected = request.headers.get("X-Render-SHA256", "").lower()
    if expected and not re.fullmatch(r"[0-9a-f]{64}", expected):
        raise HTTPException(400, "неверный SHA256")
    # 480, а не «примерно 500»: нода считает хэш ошибки ровно от первых 480 символов
    # (render_delivery.acknowledge_error) и по нему сверяет квитанцию об ошибке.
    # Хэш берём от ПРИСЛАННОГО текста, а не от подставленного нами умолчания: иначе
    # пустое сообщение превращается в «SHA256 ошибки не совпадает» на ровном месте.
    sent = (request.query_params.get("error", "") or "")[:480]
    error_hash = hashlib.sha256(sent.encode("utf-8")).hexdigest()
    err = sent or "ошибка рендера"
    supplied_error = request.headers.get("X-Render-Error-SHA256", "").lower()
    if status == "error" and supplied_error and supplied_error != error_hash:
        raise HTTPException(400, "SHA256 ошибки не совпадает")
    if t["status"] != "running":
        # Повтор доставки после обрыва ответа — не повод городить второй файл: пришло
        # то же самое → та же квитанция. Пустой X-Render-SHA256 здесь не «то же самое»,
        # а «сверить нечем»: подтверждать приём вслепую нельзя, это разрешение ноде
        # удалить ролик. Другой результат на ту же задачу → отказ.
        same = ((status == "done" and t["status"] == "done"
                 and expected and expected == t["render_sha256"])
                or (status == "error" and t["status"] == "error"
                    and error_hash == t["render_error_sha256"]))
        if not same:
            raise HTTPException(409, "другой результат уже принят")
        return JSONResponse(await run_in_threadpool(_render_receipt, t))
    proj = _project_dir(t["tenant_id"], t["project_id"])
    render_dir = os.path.join(proj, "render")
    stage = None
    size = 0
    digest = None
    try:
        if status == "done":
            f, stage = _render_staged_file(render_dir)
            h = hashlib.sha256()
            with f:
                async for chunk in request.stream():
                    if not chunk:
                        continue
                    size += len(chunk)
                    if size > RENDER_MAX_BYTES:
                        raise HTTPException(413, f"MP4 больше потолка {RENDER_MAX_BYTES} байт")
                    await run_in_threadpool(f.write, chunk)
                    h.update(chunk)
                await run_in_threadpool(f.flush)
                # fsync до проверок и до replace: принять файл, который ещё в кэше,
                # значит разрешить ноде удалить копию того, чего на диске нет.
                await run_in_threadpool(os.fsync, f.fileno())
            digest = h.hexdigest()
            # «Если прислано»: наш стендовый пуллер этих заголовков не шлёт. Пустой
            # заголовок = проверять нечем; непустой и неверный = тело битое.
            length = request.headers.get("Content-Length")
            if length and (not length.isdigit() or int(length) != size):
                raise HTTPException(400, "тело не совпало с объявленным Content-Length")
            if size < 1024:
                raise HTTPException(400, "пустой mp4 от пуллера")
            if expected and digest != expected:
                raise HTTPException(400, "SHA256 MP4 не совпадает")

        def commit_result():
            """Финал одной транзакцией BEGIN IMMEDIATE: состояние перечитывается, claim
            проверяется заново. Между началом заливки (минуты) и этой секундой задачу
            могли отменить, удалить или перезахватить другой нодой."""
            nonlocal stage
            c = db()
            try:
                c.execute("PRAGMA synchronous=FULL")
                c.execute("BEGIN IMMEDIATE")
                live = _render_row(jid, c)
                _require_render_claim(request, live)
                if live["status"] != "running":
                    same = ((status == "done" and live["status"] == "done"
                             and digest == live["render_sha256"])
                            or (status == "error" and live["status"] == "error"
                                and error_hash == live["render_error_sha256"]))
                    if not same:
                        raise HTTPException(409, "состояние рендера изменилось во время загрузки")
                    c.rollback()
                    return _render_receipt(live), False
                if status == "done":
                    # Имя результата прежнее: его знают find_video (фолбэк «штатное имя»),
                    # карточка проекта и уборщики. Защита здесь не в имени, а в том, что
                    # под этим именем оказывается только проверенный целиком файл.
                    out_rel = f"render/{jid}.mp4"
                    os.replace(stage, os.path.join(proj, out_rel))
                    stage = None
                    _render_fsync_dir(render_dir)
                    c.execute("UPDATE queue_tasks SET status='done', progress=100, stage='done', "
                              "output_rel=?, render_sha256=?, render_size=?, finished=? WHERE job_id=?",
                              (out_rel, digest, size, _now(), jid))
                    c.execute("UPDATE gen_jobs SET status='done',error=NULL WHERE id=?", (jid,))
                else:
                    c.execute("UPDATE queue_tasks SET status='error', error=?, render_error_sha256=?, "
                              "finished=? WHERE job_id=?", (err, error_hash, _now(), jid))
                    c.execute("UPDATE gen_jobs SET status='error',error=? WHERE id=?", (err, jid))
                c.commit()
                # Квитанцию считаем по УЖЕ записанной строке и по файлу на диске: если
                # между replace и коммитом что-то разошлось, нода узнает об этом сразу.
                return _render_receipt(_render_row(jid, c)), status == "done"
            except Exception:
                c.rollback()
                raise
            finally:
                c.close()

        receipt, accepted_now = await run_in_threadpool(commit_result)
    finally:
        # Временный файл не переживает запрос ни при каком исходе: ни при 400, ни при
        # отмене задачи, ни при обрыве соединения. Иначе .incoming-* копятся молча.
        if stage:
            try:
                os.unlink(stage)
            except OSError:
                pass
    if accepted_now:
        # Главы: считаются ПОСЛЕ рендера, потому что таймкоды берутся из транскрипта, который
        # рендер-нода снимает тем же whisper-прогоном, что и синхрон картинок. Ставим только
        # если транскрипт реально доехал — иначе задача упала бы с «нет транскрипта».
        try:
            _p = _get_project(t["tenant_id"], t["project_id"])
            _st = _psettings(_p) if _p else {}
            # Решает выбор, с которым запускали ИМЕННО этот рендер (params задачи);
            # настройки проекта — фолбэк для задач, поставленных до этой фичи.
            try:
                _rp = json.loads(t["params"]) if t["params"] else {}
            except Exception:
                _rp = {}
            _st = {**_st, **(_rp if isinstance(_rp, dict) else {})}
            if _truthy(_st.get("auto_chapters"), False) and t["uid"]:
                if os.path.exists(os.path.join(proj, "chapters", "transcript.json")):
                    _enqueue(t["uid"], t["tenant_id"], t["project_id"], "chapters",
                             {k: v for k, v in _st.items() if k.startswith("chapters_")})
                else:
                    _log_line(jid, "⚠️ Главы включены, но рендер-нода не прислала транскрипт — "
                               "пропускаю (нужна свежая версия render_worker/puller на ноде)")
        except Exception as e:
            _log_line(jid, f"⚠️ Главы не поставлены: {e}")
    return JSONResponse(receipt)


_TRANSCRIPT_MAX_BYTES = 8 * 1024 * 1024      # 2 ч речи ≈ 270 КБ; 8 МБ — заведомый потолок


@app.post("/api/render/{jid}/transcript")
async def render_transcript(jid: int, request: Request):
    """Пуллер отдаёт chapters/transcript.json (сегменты whisper) СЫРЫМ body — до mp4.

    Транскрипт — побочный продукт того же whisper-прогона, которым рендер синкает картинки
    с озвучкой. Присылать его отдельным запросом дешевле, чем гонять whisper второй раз на
    сервере: 2-часовой ролик — это ~5 минут CPU, которых у VPS нет.
    """
    _require_puller(request)
    c = db(); t = c.execute("SELECT tenant_id, project_id, status, claim_token FROM queue_tasks "
                            "WHERE job_id=? AND kind='render'", (jid,)).fetchone(); c.close()
    if not t:
        raise HTTPException(404)
    _require_render_claim(request, t)
    if t["status"] != "running":
        raise HTTPException(409, "render job отменён или завершён")
    buf = bytearray()
    async for chunk in request.stream():
        if chunk:
            buf.extend(chunk)
            if len(buf) > _TRANSCRIPT_MAX_BYTES:
                raise HTTPException(413, "транскрипт больше 8 МБ")
    try:
        data = json.loads(buf.decode("utf-8"))
        segs = data.get("segments")
        if not isinstance(segs, list) or not segs:
            raise ValueError("нет сегментов")
    except Exception as e:
        # Битый транскрипт молча не сохраняем: иначе главы посчитались бы по мусору.
        raise HTTPException(400, f"транскрипт не разобран: {str(e)[:120]}")
    proj = _project_dir(t["tenant_id"], t["project_id"])
    out_dir = os.path.join(proj, "chapters")
    os.makedirs(out_dir, exist_ok=True)
    dst = os.path.join(out_dir, "transcript.json")
    tmp = dst + ".tmp"
    with open(tmp, "wb") as f:
        f.write(buf)
    os.replace(tmp, dst)
    return JSONResponse({"ok": True, "segments": len(segs)})


@app.get("/api/render/{jid}/download")
async def render_download(jid: int, request: Request):
    """Партнёр скачивает готовый mp4 (session-auth)."""
    u = require_web_user(request)
    tid = _tid(u)
    c = db(); t = c.execute("SELECT * FROM queue_tasks WHERE job_id=? AND tenant_id=?", (jid, tid)).fetchone(); c.close()
    if not t or t["kind"] != "render" or t["status"] != "done" or not t["output_rel"]:
        raise HTTPException(404, "нет готового файла")
    path = os.path.join(_project_dir(tid, t["project_id"]), t["output_rel"])
    if not os.path.exists(path):
        raise HTTPException(404)
    proj = _get_project(tid, t["project_id"])
    base = re.sub(r"[^\w\-]+", "_", (proj["name"] if proj else "video"))[:60] or "video"
    return FileResponse(path, media_type="video/mp4", filename=base + ".mp4")


@app.post("/api/render/{jid}/delete")
async def render_delete(jid: int, request: Request):
    """Удалить рендер: mp4 с диска + строку задачи из списка «Мои рендеры».

    Работает в любом состоянии. Идущую сборку это же и останавливает: у ноды
    следующий post_progress по удалённой строке получит 409, и пуллер бросит рендер
    (см. tools/render_puller.py: 409 → False → выход). Сироты на диске не остаётся —
    mp4 пишет сервер в /api/render/{jid}/result, а без строки он туда не дойдёт.
    """
    u = require_web_user(request)
    tid = _tid(u)
    c = db()
    t = c.execute("SELECT * FROM queue_tasks WHERE job_id=? AND tenant_id=?",
                  (jid, tid)).fetchone()
    c.close()
    if not t or t["kind"] != "render":
        raise HTTPException(404, "нет такого рендера")
    pid = t["project_id"]
    projdir = os.path.abspath(_project_dir(tid, pid))
    # Файл берём только из output_rel и только изнутри каталога проекта.
    rel = (t["output_rel"] or "").replace("\\", "/").lstrip("/")
    if rel:
        full = os.path.abspath(os.path.join(projdir, rel))
        if (full == os.path.join(projdir, *rel.split("/"))
                and full.startswith(projdir + os.sep) and os.path.isfile(full)):
            try:
                os.remove(full)
            except OSError:
                pass
    c = db()
    c.execute("DELETE FROM queue_tasks WHERE job_id=? AND tenant_id=? AND kind='render'",
              (jid, tid))
    c.execute("DELETE FROM job_logs WHERE job_id=?", (jid,))
    # Строку gen_jobs НЕ трогаем намеренно: это реестр номеров задач. Номер берётся как
    # max(rowid gen_jobs, job_id queue_tasks)+1 (см. _enqueue), и если вычистить обе таблицы,
    # счётчик откатится назад и следующая задача переиспользует только что освобождённый id.
    # Пометка «удалён» держит номер занятым; пользователю эта строка нигде не видна.
    c.execute("UPDATE gen_jobs SET status='deleted', error=NULL WHERE id=?", (jid,))
    c.commit()
    c.close()
    if request.headers.get("X-Requested-With") == "fetch":
        return {"ok": True}
    return RedirectResponse(f"/p/{pid}?tab=rnd", 302)


@app.get("/api/jobs/{jid}/logs")
async def job_logs_sse(jid: int, request: Request):
    u = web_user(request)
    if not u:
        raise HTTPException(401)
    tid = _tid(u)
    c = db(); t = c.execute("SELECT tenant_id FROM queue_tasks WHERE job_id=?", (jid,)).fetchone(); c.close()
    if not t or t["tenant_id"] != tid:
        raise HTTPException(403)

    # + свои ключи владельца тенанта: BYOK-секрет тоже не должен доехать до экрана
    sse_secrets = (_all_server_credential_values()
                   + _own_credential_secret_values(_user_own_credentials(u)))

    def _clean(line):
        safe = _redact_worker_output(line or "", extra_secrets=sse_secrets)
        return safe.replace("\r", "").replace("\n", " ")

    async def gen():
        import asyncio
        # 1) НАЧАЛЬНЫЙ бэклог — пакетами (одно SSE-событие на ~800 строк вместо тысяч кадров) →
        #    мгновенная отрисовка даже для логов на 15k строк. Индекс (job_id,id) делает выборку быстрой.
        MAXB = 3000   # кап хвоста: огромные логи (до 15k строк) не грузим целиком — тянем последние 3000
        c = db()
        total = c.execute("SELECT COUNT(*) FROM job_logs WHERE job_id=?", (jid,)).fetchone()[0]
        if total > MAXB:
            rows = c.execute("SELECT id,line FROM job_logs WHERE job_id=? ORDER BY id DESC LIMIT ?",
                             (jid, MAXB)).fetchall()[::-1]   # индекс (job_id,id) → дешёвый забор с конца
        else:
            rows = c.execute("SELECT id,line FROM job_logs WHERE job_id=? ORDER BY id", (jid,)).fetchall()
        st = c.execute("SELECT status FROM queue_tasks WHERE job_id=?", (jid,)).fetchone()
        c.close()
        last = rows[-1]["id"] if rows else 0
        if total > MAXB:
            yield f"data: … показаны последние {MAXB} строк из {total} (начало лога скрыто для скорости) …\n\n"
        CH = 800
        for i in range(0, len(rows), CH):
            yield "data: " + "\ndata: ".join(_clean(r["line"]) for r in rows[i:i + CH]) + "\n\n"
        status = st["status"] if st else "?"
        if status in ("done", "error", "cancelled"):
            yield f"event: end\ndata: {status}\n\n"
            return
        # 2) ЖИВОЙ хвост — построчно, короткими опросами (только новые строки, id>last по индексу)
        idle = 0
        while True:
            c = db()
            rows = c.execute("SELECT id,line FROM job_logs WHERE job_id=? AND id>? ORDER BY id", (jid, last)).fetchall()
            st = c.execute("SELECT status FROM queue_tasks WHERE job_id=?", (jid,)).fetchone()
            c.close()
            for r in rows:
                last = r["id"]
                yield "data: " + _clean(r["line"]) + "\n\n"
            status = st["status"] if st else "?"
            if status in ("done", "error", "cancelled"):
                yield f"event: end\ndata: {status}\n\n"
                break
            yield ": ping\n\n"
            await asyncio.sleep(0.8)
            idle += 1
            if idle > 2400:   # ~32 мин страховка
                yield "event: end\ndata: timeout\n\n"; break

    return StreamingResponse(gen(), media_type="text/event-stream")


@app.post("/api/jobs/{jid}/cancel")
async def job_cancel(jid: int, request: Request):
    u = require_web_user(request)
    tid = _tid(u)
    c = db(); c.execute("BEGIN IMMEDIATE")
    t = c.execute("SELECT tenant_id,status FROM queue_tasks WHERE job_id=?", (jid,)).fetchone()
    if not t or t["tenant_id"] != tid:
        c.rollback(); c.close()
        raise HTTPException(403)
    if t["status"] not in ("queued", "running"):
        c.rollback(); c.close()
        raise HTTPException(409, "задача уже завершена")
    cur = c.execute("UPDATE queue_tasks SET status='cancelled', finished=?, "
                    "claim_token=NULL, claimed=NULL "
                    "WHERE job_id=? AND status IN ('queued','running')", (_now(), jid))
    if cur.rowcount != 1:
        c.rollback(); c.close()
        raise HTTPException(409, "задача уже завершена")
    c.execute("UPDATE gen_jobs SET status='cancelled' WHERE id=?", (jid,))
    c.execute("UPDATE card_jobs SET status='cancelled', finished=?, error_code='cancelled', "
              "last_error='cancelled' WHERE job_id=?", (_now(), jid))
    c.commit(); c.close()
    CANCELLED.add(jid)
    with RUNNING_LOCK:
        proc = RUNNING_PROCS.get(jid)
    if proc:
        _kill_proc(proc)
    _log_line(jid, "⏹ отменено пользователем")
    if request.headers.get("X-Requested-With") == "fetch":
        return {"ok": True}
    return RedirectResponse("/queue", 302)


@app.post("/api/jobs/{jid}/retry")
async def job_retry(jid: int, request: Request):
    """Повторить упавшую/отменённую задачу — новая постановка с теми же параметрами."""
    u = require_web_user(request)
    tid = _tid(u)
    c = db()
    t = c.execute("SELECT * FROM queue_tasks WHERE job_id=?", (jid,)).fetchone()
    c.close()
    if not t or t["tenant_id"] != tid:
        raise HTTPException(403)
    if t["status"] not in ("error", "cancelled"):
        raise HTTPException(409, "повтор доступен только для ошибочной или отменённой задачи")
    if t["kind"] == "cards":
        if not _provider_available_for(u, card_contract.PROVIDER_GROUP):
            raise HTTPException(400, f"{_provider_title(card_contract.PROVIDER_GROUP)}: {NO_SERVER_KEY_HINT}")
        _retry_card_task(jid, tid)
        return ({"ok": True, "job_id": jid}
                if request.headers.get("X-Requested-With") == "fetch"
                else RedirectResponse("/queue", 302))
    if t["kind"] in ("prompts", "images", "regen"):
        conflict = _active_image_mutation(tid, t["project_id"])
        if conflict:
            raise HTTPException(
                409,
                f"картинки проекта уже меняются задачей #{conflict['job_id']} "
                f"({conflict['kind']}); дождитесь её завершения",
            )
    elif _active_task(tid, t["project_id"], t["kind"]):
        raise HTTPException(409, "такая задача проекта уже в очереди или выполняется")
    task_failover = _prompt_failover_from_row(t)
    prompt_snapshot = _PROMPT_FAILOVER_UNSET
    if t["kind"] == "prompts" and task_failover == _PROMPT_FAILOVER_DISABLED:
        prompt_snapshot = t["provider"]
        if prompt_snapshot not in _PROMPT_PROVIDER_GROUPS:
            raise HTTPException(409, "у закреплённой задачи повреждён snapshot prompt-provider")
    try:
        params = json.loads(t["params"] or "{}")
    except Exception:
        params = {}
    reference_bundle_id = params.pop(_REFERENCE_BUNDLE_PARAM, _REFERENCE_BUNDLE_UNSET)
    # Проект без сценария: «Повторить» — ТРЕТИЙ человеческий вход к платной постановке
    # (после батча и одиночных кнопок), и правило «нет сценария — не платим» обязано
    # стоять и здесь. Строка очереди хранит параметры момента падения, а сценарий с тех
    # пор могли стереть или проект пересоздать — тогда повтор молча оплатил бы
    # раскадровку и озвучку пустоты. Раньше проверки ключей и раньше отложенного
    # рендера — по той же причине, что и в gen_submit: пустой сценарий человек чинит
    # сам и сразу, а разговор про ключи на пустом проекте бессмыслен.
    _assert_source_text(tid, t["project_id"], (t["kind"],), params)
    _is_fetch = request.headers.get("X-Requested-With") == "fetch"
    if t["kind"] == "render" and not _render_inputs_ready(tid, t["project_id"]):
        _save_project_settings(tid, t["project_id"], {"deferred_pending": t["uid"] or u["id"]})
        return {"ok": True, "deferred": True} if _is_fetch else RedirectResponse("/queue", 302)
    if t["kind"] != "render":
        # Тот же гвард, что на постановке (gen_submit): задача упала «нет ключа» —
        # «Повторить» не должен снова ставить её в очередь под тот же провал.
        if prompt_snapshot is not _PROMPT_FAILOVER_UNSET:
            if not _provider_available_for(u, prompt_snapshot):
                raise HTTPException(400, f"{_provider_title(prompt_snapshot)}: {NO_SERVER_KEY_HINT}")
        else:
            _assert_provider_available(
                u, t["kind"], params, project_id=t["project_id"]
            )
        if t["kind"] == "images" and _needs_scene_plan(tid, t["project_id"], params):
            _assert_provider_available(
                u, "prompts", params, project_id=t["project_id"]
            )
    try:
        njid = _enqueue(
            t["uid"] or u["id"], tid, t["project_id"], t["kind"], params,
            prompt_failover=task_failover,
            prompt_provider_snapshot=prompt_snapshot,
            reference_bundle_id=reference_bundle_id,
        )
    except (ImageModeContractError, reference_contract.ReferenceContractError) as exc:
        raise HTTPException(409, f"повреждён контракт исходной задачи: {exc}")
    if njid is None:
        raise HTTPException(409, "такая задача проекта уже в очереди или выполняется")
    return {"ok": True} if _is_fetch else RedirectResponse("/queue", 302)


